    "text": "Η CT εγκεφάλου έχει εξαιρετικά υψηλή ευαισθησία (σχεδόν 100%) στην ανίχνευση της οξείας αιμορραγίας από τα πρώτα κιόλας λεπτά. Το αίμα εμφανίζεται ως \"λευκή\" (υπέρπυκνη) περιοχή και διακρίνεται αμέσως. Έμφρακτο (Ισχαιμία): Αντίθετα, τις πρώτες 6-12 ώρες, η αξονική τομογραφία έχει χαμηλή ευαισθησία για την ανίχνευση ενός ισχαιμικού εμφράκτου. Οι αλλοιώσεις της ισχαιμίας μπορεί να μην είναι ορατές πριν περάσουν αρκετές ώρες (συχνά >12-24 ώρες). Η μαγνητική τομογραφία (MRI) είναι πολύ πιο ευαίσθητη στην πρώιμη φάση του εμφράκτου."
