  "question": "Υπηρετείτε ως αγροτικός και εφημερεύετε σε νοσοκομείο υπαίθρου όπου σας προσκομίζουν νεογνό ηλικίας 3 εβδομάδων με πυρετό, ευερεθιστότητα και μείωση της πρόσληψης τροφής. Η εξέταση ΕΝΥ αναδεικνύει: κύτταρα 600/ml (80% πολυμορφοπύρηνα), λεύκωμα 160mg/dl, γλυκόζη 20 mg/dl (σάκχαρο αίματος 90 mg/dl), Οι αιμοκαλλιέργειες είναι θετικές για Gram αρνητικό βακτηρίδιο με ροζ αποικίες στο MacConkey άγαρ. Ποιο είναι το πιθανότερο παθογόνο;",
