  "question": "Υπηρετείτε ως αγροτικός και εφημερεύετε σε νοσοκομείο υπαίθρου όπου σας προσκομίζουν κορίτσι ηλικίας 3 ετών με διάχυτο ερυθηματώδες εξάνθημα σαν δίκτυ, που ξεκίνησε μετά το πρωινό με εντόπιση στο στομάχι, στην ράχη και στα άκρα. Δύο ημέρες πριν το κορίτσι εμφάνισε ερύθημα παρειών. Αναφέρει ρινική συμφόρηση, κεφαλαλγία πριν την εμφάνιση του εξανθήματος και ο νεότερος αδελφός της είχε ακριβώς τα ίδια συμπτώματα που εξαφανίσθηκαν χωρίς παρέμβαση. Τι ισχύει;",
